 24: function Read-Ws([System.Net.WebSockets.ClientWebSocket]$Socket) {
 25:     $buffer = New-Object byte[] 65536
 26:     $segment = New-Object System.ArraySegment[byte] -ArgumentList @(,$buffer)
 27:     $stream = [System.IO.MemoryStream]::new()
 28:     try {
 29:         do {
 30:             $result = $Socket.ReceiveAsync($segment, [Threading.CancellationToken]::None).GetAwaiter().GetResult()
 31:             if ($result.MessageType -eq [System.Net.WebSockets.WebSocketMessageType]::Close) { throw 'VISUAL362_MCP_CLOSED' }
 32:             if ($result.Count -gt 0) { $stream.Write($buffer, 0, $result.Count) }
 33:         } while (-not $result.EndOfMessage)
 34:         [Text.Encoding]::UTF8.GetString($stream.ToArray())
 35:     }
 36:     finally { $stream.Dispose() }
 37: }
