 39: function Invoke-McpRaw([string]$Method, [hashtable]$Params) {
 40:     $script:mcpId++
 41:     $payload = @{ jsonrpc='2.0'; id=$script:mcpId; method=$Method; params=$Params } | ConvertTo-Json -Depth 24 -Compress
 42:     $bytes = [Text.Encoding]::UTF8.GetBytes($payload)
 43:     $segment = New-Object System.ArraySegment[byte] -ArgumentList @(,$bytes)
 44:     [void]$ws.SendAsync($segment,[System.Net.WebSockets.WebSocketMessageType]::Text,$true,[Threading.CancellationToken]::None).GetAwaiter().GetResult()
 45:     $response = (Read-Ws $ws) | ConvertFrom-Json
 46:     $errorValue = if ($response.PSObject.Properties['error']) { $response.error } else { $null }
 47:     if ($errorValue) { throw ('VISUAL362_MCP_ERROR ' + ($errorValue | ConvertTo-Json -Compress)) }
 48:     $response.result
 49: }
