 51: function Invoke-McpTool([string]$Name,[hashtable]$Arguments) {
 52:     $result = Invoke-McpRaw 'tools/call' @{ name=$Name; arguments=$Arguments }
 53:     if (-not $result.content -or @($result.content).Count -lt 1) { throw "VISUAL362_EMPTY_TOOL_RESULT tool=$Name" }
 54:     $wrapped = $result.content[0].text | ConvertFrom-Json
 55:     $wrappedError = if ($wrapped.PSObject.Properties['error']) { $wrapped.error } else { $null }
 56:     if ($wrappedError) { throw "VISUAL362_TOOL_WRAPPER_ERROR tool=$Name error=$wrappedError" }
 57:     $value = $wrapped.value
 58:     $valueError = if ($null -ne $value -and $value.PSObject.Properties['error']) { $value.error } else { $null }
 59:     $valueSuccess = if ($null -ne $value -and $value.PSObject.Properties['success']) { $value.success } else { $null }
 60:     if ($null -eq $value -or $valueError -or $valueSuccess -eq $false) { throw "VISUAL362_TOOL_FAILED tool=$Name value=$($value | ConvertTo-Json -Depth 12 -Compress)" }
 61:     $value
 62: }
