 64: function Close-Mcp {
 65:     if ($script:ws) {
 66:         if ($script:ws.State -eq [System.Net.WebSockets.WebSocketState]::Open) {
 67:             try { [void]($script:ws.CloseAsync([System.Net.WebSockets.WebSocketCloseStatus]::NormalClosure,'visual362',[Threading.CancellationToken]::None).GetAwaiter().GetResult()) } catch {}
 68:         }
 69:         $script:ws.Dispose()
 70:         $script:ws = $null
 71:     }
 72: }
